checks = {}
def check(name, value, detail=''):
    checks[name] = {'passed': bool(value), 'detail': detail}

check('production QA uses a single gated namespace', 'if(IS_QA_BUILD)window.RizoRuntimeQA=createRizoRuntimeQA()' in js)
