check('completion verifies full resolution', 'd.currentWave<=d.clearedWave' in js and '!isWaveFullyResolved(d))return false' in js)
check('child queue blocks completion', 'd.childSpawnQueue.length===0' in js)
check('rewards calculate from clearedWave', 'calculateRunEmbers({clearedWave,' in js)
check('zero-clear runs cannot advance mastery', 'if(clearedWave>0)for(const row of persistentLeaders)' in js)
check('run outcomes are explicit', 'finishDefenseRunWithMoment("banked")' in js and 'finishDefenseRunWithMoment("gate")' in js and 'ended:snapshot.ended==="gate"?"gate":"banked"' in js)
check('history migration preserves reached wave', 'reachedWave = Math.max(clearedWave' in js and 'clearedWave,' in js)
check('golden bonus only has one implementation', len(re.findall(r'^\s{2}function defenseGoldenBonus\(', js, re.M)) == 1)
check('gameplay density uses centralized invariant core', 'DefenseCore.densityCap' in js and 'speedRoom = speed === 2 ? 2 : 0' not in js)
check('explicit upgrade costs are active', 'DefenseCore.upgradeCost' in js and '110 + 80 * upgrade' not in js)
check('simulation and control clocks are separated', 'realClock:0' in js and 'd.realClock=(d.realClock||0)+safeRealDt' in js and 'd.clock+=dt' in js)
check('v76 uses fixed 30hz simulation with bounded catch-up', 'stepHz: 30' in core and 'maxCatchUpSteps: 4' in core and 'advanceDefenseFixedFrame' in js and 'simAccumulator' in js)
check('presentation interpolates simulation snapshots', 'renderDefensePresentation' in js and 'enemy.prevX+(enemy.x-enemy.prevX)*blend' in js)
check('adaptive governor tracks p95 and degrades presentation first', 'frameP95' in js and 'governorTier' in js and 'presentationFps' in core and 'performanceLow=(d.governorTier||0)>=2' in js)
check('logical projectile simulation is decoupled from visual emission', 'projectileEmissionHz' in core and 'coalescedVisualShots' in js and 'defenseVisibleProjectileCount' in js)
check('speed and quality do not secretly thin gameplay density', 'void low; void speed;' in core and 'DefenseCore.densityCap({low:false' in js)
check('manual wave boundaries remain default with optional auto waves', 'defenseAutoStart: false' in js and 'data-defense-auto-start' in js and 'autoStartAtReal' in js)
check('target refresh uses simulation time and cached references', 'realTime=time,budget=DEFENSE_BUDGETS.normal' in js and 'tower.targetRef' in js and 'targetSnapshotAtReal' in js)
check('split children use deterministic game-time release', 'releaseAt:d.clock+Math.max(.04,delay)' in js and 'child.releaseAt>d.clock' in js and 'childSpawnsReleased' in js)
check('child buffer is not sorted every frame', '.childSpawnQueue.sort(' not in js)
check('density reserves imminent child spawns', 'DefenseCore.childReservationCount' in js)
