check('income flush cadence uses wall time', 'nextIncomeFlushAtReal' in js and 'lastIncomeBatch' in js)
check('v87 checkpoint migrates v80 and older data', 'defense-checkpoint-v68' in js and 'defense-checkpoint-v67' in js and '[1,2,3,4,5,6,7,8,9,DEFENSE_CHECKPOINT_VERSION]' in js)
check('new service worker cache matches build', 'rizo-game-v87-first-ten' in sw and 'defense-core-v79.js' in sw and 'game-v79-defense.js' in sw and 'game-v63-art-direction.js' not in sw)
check('index build metadata matches v87', index.count('v87-first-ten') >= 2 and 'v75-arcade-revival' not in index)
check('index loads active defense assets', 'defense-core-v79.js' in index and 'defense-canvas-v79.js' in index and 'game-v79-defense.js' in index and 'launch-v79-defense-alive.css' in index)
