check('media query count reduced', css.count('@media') <= 30, f"count={css.count('@media')}")
check('important count materially reduced', css.count('!important') < 400, f"count={css.count('!important')}")
# Stylesheet budgets. The original single-file cap guarded only
# launch-v79-defense-alive.css, which every specialist stylesheet
# (worker-b-economy, worker-d-towers, worker-e-abilities-depth, worker-h-ui,
# rtd-worker-i-feel, rtd-defense-integration) trivially sidestepped by shipping a
# sibling file. Guard both: the core stylesheet still may not drift far from its
# refactored size, and the total payload the browser actually downloads now has a
# real ceiling, so adding another stylesheet can no longer hide growth.
shipped_css = re.findall(r'<link href="\./([A-Za-z0-9_.-]+\.css)" rel="stylesheet"', index)
shipped_bytes = sum(len((root/name).read_bytes()) for name in shipped_css if (root/name).exists())
check('core defense stylesheet stays near its refactored size', len(css) < 310_000, f"bytes={len(css)}")
check('total shipped stylesheet payload stays inside the integrated budget', shipped_bytes < 560_000, f"files={len(shipped_css)} bytes={shipped_bytes}")
check('obsolete per-world starting cash removed', not re.search(r'const DEFENSE_MAPS[\s\S]{0,12000}?cash:\d+', js))
check('phase 5 economy is centralized in core', 'const ECONOMY = Object.freeze' in (root/'defense-core-v79.js').read_text() and 'baseStartingCash: 220' in (root/'defense-core-v79.js').read_text())
check('late economy uses normalized bounty and late deployment growth', 'packNormalization' in (root/'defense-core-v79.js').read_text() and 'deployLateGrowth: 1.62' in (root/'defense-core-v79.js').read_text() and 'UPGRADE_COSTS = Object.freeze([110, 180, 320, 640])' in (root/'defense-core-v79.js').read_text())
