check('canonical enemy and boss/heavy kill rewards remain defined', len(catalog_rewards) == 17 and min(catalog_rewards, default=0) > 0, f"count={len(catalog_rewards)} rewards={catalog_rewards}")
check('deployment cost is canonical and not duplicated in runtime', 'DefenseCore.deploymentCost' in js and '145*Math.pow(1.36' not in js)
check('planning refund and undo use centralized wall-time rules', 'DefenseCore.ECONOMY.planningRefundRate' in js and 'DefenseCore.ECONOMY.placementUndoSeconds' in js and 'placedAtReal:defenseRealNow(d)' in js)
check('combat economy permissions use phase model with live upgrades', 'function defenseUpgradeAllowed' in js and 'function defensePlacementAllowed' in js and 'function defenseSellAllowed' in js and 'SAFE WINDOW REQUIRED' not in js)
check('world opening perks are explicit and one-shot', 'DEFENSE_WORLD_OPENING_PERKS' in js and 'worldOpeningDiscount' in js and 'openingPerkApplied' in js and 'worldPerkUsed' in js)
check('Golden global and active income use capped core functions', 'DefenseCore.goldenBonus' in js and 'DefenseCore.goldenActivePayout' in js and 'gain=45+d.currentWave' not in js)
check('v5 checkpoint signature covers opening economy state', 'signatureVersion >= 5' in (root/'defense-core-v79.js').read_text() and 'signedTower.openingPerkApplied' in (root/'defense-core-v79.js').read_text() and 'modern.worldPerkUsed' in (root/'defense-core-v79.js').read_text())
boot=index
headers=(root/'_headers').read_text()
config=(root/'rizo-config.js').read_text()
core=(root/'defense-core-v79.js').read_text()
check('bosses reserve a dedicated final packet entrance', 'Bosses own the last beat' in core and 'packets.push({ enemies: [bossEntry], spawnGap: 1.10, breakAfter: 0 })' in core)
check('obsolete runtime spawn pacing workarounds are removed', 'function defenseSpawnGap(' not in js and 'function defenseSpawnClearance(' not in js)
check('phase transitions are explicit and validated', 'PHASE_TRANSITIONS' in core and 'canTransitionPhase' in core and 'phase-transition-rejected' in js)
check('persistent phase HUD shows active and cleared waves separately', 'id="defenseWave"' in js and 'id="defenseClearedWave"' in js and 'id="defensePhaseIndicator"' in js)
check('context overlays use one manager with inert background', 'syncDefenseOverlayState' in js and 'defenseContextSurface' in js and '.inert=' in js and 'data-defense-dismiss-context' in js)
check('context keyboard handling traps focus and handles Escape', 'defenseHandleContextKeydown' in js and 'event.key==="Escape"' in js and 'event.key!=="Tab"' in js)
check('portrait shell has an explicit minmax column contract', 'grid-template-columns: minmax(0, 1fr); grid-template-rows:' in css)
check('short portrait preserves hearts, gold, wave and phase', '.defense-command-world { display:none; }' in css and 'grid-template-columns:repeat(3,minmax(44px,1fr))' in css and '#defenseWaveLabel { display:block; }' in css)
check('large cash is compacted only at HUD presentation', 'function defenseHudCounter' in js and 'cash.textContent=defenseHudCounter(exact)' in js)
