check('automatic install gate is disabled at launch', 'enabled: false' in config)
check('service worker core runtime is network first', 'NETWORK_FIRST_PATHS' in sw and 'networkFirst(request)' in sw and 'fetch(request, { cache: "no-store" })' in sw)
check('service worker optional shell cannot fail update atomically', 'cache.addAll(REQUIRED_SHELL)' in sw and 'Promise.allSettled' in sw)
check('service worker converges after complete shell cache', 'await self.skipWaiting()' in sw and 'self.clients.claim()' in sw)
check('deployment MIME and cache headers are explicit', 'X-Content-Type-Options: nosniff' in headers and '/*.js' in headers and 'Content-Type: application/javascript' in headers and '/*.css' in headers and 'Content-Type: text/css' in headers)
active_text = '\n'.join([index, css, js, sw])
asset_refs = sorted(set(re.findall(r'\./assets/[A-Za-z0-9_./-]+\.(?:png|webp|svg|jpg|jpeg|gif|mp3|wav|ogg)', active_text, re.I)))
missing_assets = [ref for ref in asset_refs if not (root/ref[2:]).exists()]
check('all active local assets exist', not missing_assets, f"refs={len(asset_refs)} missing={missing_assets[:8]}")

# Phase 7 battlefield art cohesion contracts.
check('phase 7 structural world feature layer is canonical', 'function defenseWorldFeatureMarkup(map)' in js and '<div class="defense-world-features">${defenseWorldFeatureMarkup(map)}</div>' in js)
check('all six worlds define authored terrain feature identities', all(token in js for token in ['root','vine','vent','crack','orbit','crater','puddle','wind','bank','lane','reveal']))
landmark_block = re.search(r'\.defense-landmark\s*\{([^}]*)\}', css, re.S)
check('generic landmark rule no longer flattens authored silhouettes', bool(landmark_block) and 'width:' not in landmark_block.group(1) and 'height:' not in landmark_block.group(1) and 'background:' not in landmark_block.group(1), landmark_block.group(1).strip() if landmark_block else 'missing')
check('road fill weight is reduced from legacy width', '.defense-road-fill { stroke:var(--road-fill); stroke-width:58;' in css and 'stroke-width:67' not in css)
check('adaptive gameplay contrast variables exist for all worlds', css.count('--play-outline:') >= 7 and css.count('--play-halo:') >= 7, f"outline={css.count('--play-outline:')} halo={css.count('--play-halo:')}")
check('tower and enemy geometry share bounded world scale', 'clamp(d.renderWidth/390,.86,1.16)' in js and 'width:calc(62px * var(--def-unit-scale))' in css and 'width:calc(36px * var(--def-unit-scale))' in css)
check('selected tower uses dedicated ground range surface', '.defense-tower.selected .defense-range { opacity:1; }' in css and '.defense-range {' in css)
check('placement pockets carry world identity classes', 'build-pocket-${escapeHTML(map.id)}' in js and all(f'.build-pocket-{m}' in css for m in ['ember','moon','storm','blizzard','eclipse']))
check('route markers are quiet until explicit trace state', '.defense-route-marker {' in css and 'opacity:0;' in css and '.defense-world.route-tracing .defense-route-marker { opacity:.55; }' in css and 'route-tracing' in js)
check('development-style world labels are visually removed', '.defense-landmark span, .defense-route-marker span, .defense-entrance span, .defense-gate b { display:none; }' in css)
check('tower grounding uses foot shadow and pedestal contracts', '.defense-tower::before {' in css and '.defense-tower::after {' in css and 'translate:-50% -88%' in css)
check('phase 7 adds no defense important override debt', not re.search(r'(?:defense-|balloon-)[^{]*\{[^}]*!important', css, re.S))

out = root/'reports'/'static-defense-audit.json'
out.write_text(json.dumps(checks, indent=2))
for name, row in checks.items(): print(('PASS' if row['passed'] else 'FAIL'), name, row['detail'])
failed = [name for name,row in checks.items() if not row['passed']]
print(f"\n{len(checks)-len(failed)}/{len(checks)} static checks passed")
sys.exit(1 if failed else 0)
